from typing import TypedDict
from langgraph.graph import StateGraph, START, END

class State(TypedDict):
    question: str
    docs: list
    answer: str

def retrieve(state: State):
    return {"docs": search(state["question"])}

def generate(state: State):
    return {"answer": llm_answer(state["question"], state["docs"])}

def need_more(state: State):
    return "retrieve" if not state["docs"] else "generate"

g = StateGraph(State)
g.add_node("retrieve", retrieve)
g.add_node("generate", generate)
g.add_edge(START, "retrieve")
g.add_conditional_edges("retrieve", need_more)   # 条件边：没找到就再检索（需加次数上限）
g.add_edge("generate", END)
app = g.compile()                                  # 可传 checkpointer 实现持久化与人工介入
print(app.invoke({"question": "年假怎么算？", "docs": [], "answer": ""}))

// Java 后端调用 Dify 应用 API（阻塞模式，示意）
@Service
@RequiredArgsConstructor
public class DifyClient {
    private final RestClient rest = RestClient.builder()
            .baseUrl("https://dify.internal/v1").build();
    @Value("${dify.api-key}") private String apiKey;          // 放配置中心，勿写死

    public String chat(String userId, String query, String conversationId) {
        Map<String, Object> body = Map.of(
                "inputs", Map.of(),
                "query", query,
                "response_mode", "blocking",                   // 流式用 streaming（SSE）
                "conversation_id", conversationId == null ? "" : conversationId,
                "user", userId);
        JsonNode resp = rest.post().uri("/chat-messages")
                .header("Authorization", "Bearer " + apiKey)
                .body(body).retrieve().body(JsonNode.class);
        return resp.path("answer").asText();
    }
}

