public class PiiMaskAdvisor implements CallAdvisor {
    public ChatClientResponse adviseCall(ChatClientRequest req, CallAdvisorChain chain) {
        ChatClientRequest masked = req.mutate()
            .prompt(req.prompt().augmentUserMessage(u -> u.mutate().text(PiiMasker.mask(u.getText())).build()))
            .build();                                         // 调用模型前脱敏
        return chain.nextCall(masked);
    }
    public String getName() { return "pii-mask"; }
    public int getOrder() { return Ordered.HIGHEST_PRECEDENCE; }   // 最先执行
}
